python3 << 'PYEOF'
import os
import re
from collections import defaultdict

ROOT = "/bench/repo"
INTERNAL = os.path.join(ROOT, "internal")

# Parse function/method declarations in internal/
decl_re = re.compile(r'^func (?:\([^)]+\) )?(\*?[A-Za-z0-9_]+)?\s*([A-Za-z0-9_]+)\(')
decls = []  # (symbol, path, line, exported, package_unexported)

for dirpath, _, files in os.walk(INTERNAL):
    for fn in files:
        if not fn.endswith('.go') or fn.endswith('_test.go'):
            continue
        path = os.path.join(dirpath, fn)
        rel = os.path.relpath(path, ROOT)
        with open(path, 'r', encoding='utf-8') as f:
            for i, line in enumerate(f, 1):
                m = decl_re.match(line.strip())
                if not m:
                    continue
                recv, name = m.group(1), m.group(2)
                if name == 'init':
                    continue
                if recv:
                    recv = recv.lstrip('*')
                    symbol = f"({recv}).{name}"
                else:
                    symbol = name
                decls.append({
                    'symbol': symbol,
                    'name': name,
                    'recv': recv,
                    'path': rel,
                    'line': i,
                    'exported': name[0].isupper() if name else False,
                })

# Read all non-test go files (excluding proto/gen)
go_files = []
for dirpath, _, files in os.walk(ROOT):
    if '/proto/gen/' in dirpath or '/node_modules/' in dirpath or '/web/' in dirpath:
        continue
    for fn in files:
        if fn.endswith('.go') and not fn.endswith('_test.go'):
            go_files.append(os.path.join(dirpath, fn))

contents = {}
for path in go_files:
    rel = os.path.relpath(path, ROOT)
    with open(path, 'r', encoding='utf-8') as f:
        contents[rel] = f.read()

# Count call sites - heuristic patterns
call_counts = defaultdict(lambda: {'count': 0, 'callers': set()})

for d in decls:
    name = d['name']
    recv = d['recv']
    decl_path = d['path']

    if recv:
        # method call: recv.Name( or package.recv - harder
        patterns = [
            re.compile(r'\.' + re.escape(name) + r'\s*\('),
            re.compile(re.escape(rec) + r'\.' + re.escape(name) + r'\s*\('),
        ]
    else:
        patterns = [re.compile(r'\b' + re.escape(name) + r'\s*\(')]

    for caller_path, text in contents.items():
        if caller_path == decl_path:
            # still count calls within same file excluding decl line
            pass
        for pat in patterns:
            for m in pat.finditer(text):
                # rough filter: skip func declaration lines by checking context
                start = m.start()
                line_start = text.rfind('\n', 0, start) + 1
                line = text[line_start:text.find('\n', start)]
                if re.search(r'\bfunc\b', line):
                    continue
                call_counts[(d['symbol'], decl_path)]['count'] += 1
                call_counts[(d['symbol'], decl_path)]['callers'].add(caller_path)

# Sort by fan-in
ranked = sorted(call_counts.items(), key=lambda x: x[1]['count'], reverse=True)

print("TOP 25 by approximate call-site count:")
for (sym, path), info in ranked[:25]:
    print(f"{info['count']:4d}  {sym}  —  {path}  ({len(info['callers'])} files)")

# Also show top exported-only
print("\nTOP 15 exported:")
exported_ranked = [(k,v) for k,v in ranked if k[0].split(').')[-1][0].isupper() or (').' not in k[0] and k[0][0].isupper())]
for (sym, path), info in exported_ranked[:15]:
    print(f"{info['count']:4d}  {sym}  —  {path}  ({len(info['callers'])} files)")
