go run - <<'GOEOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type declKey struct {
	symbol string
	path   string
}

func main() {
	root := "/bench/repo"
	internal := filepath.Join(root, "internal")

	// Collect declarations in internal/
	decls := map[declKey]struct{}{}
	nameToKeys := map[string][]declKey{}

	fset := token.NewFileSet()
	_ = filepath.Walk(internal, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}
		for _, decl := range f.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Name.Name == "init" {
				continue
			}
			symbol := fn.Name.Name
			if fn.Recv != nil && len(fn.Recv.List) > 0 {
				recvType := exprString(fn.Recv.List[0].Type)
				recvType = strings.TrimPrefix(recvType, "*")
				symbol = "(" + recvType + ")." + fn.Name.Name
			}
			key := declKey{symbol: symbol, path: rel}
			decls[key] = struct{}{}
			nameToKeys[fn.Name.Name] = append(nameToKeys[fn.Name.Name], key)
		}
		return nil
	})

	fanIn := map[declKey]map[string]int{}

	_ = filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		if strings.Contains(path, "/proto/gen/") || strings.Contains(path, "/web/") {
			return nil
		}
		callerRel, _ := filepath.Rel(root, path)
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}
		ast.Inspect(f, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			var name string
			switch fun := call.Fun.(type) {
			case *ast.Ident:
				name = fun.Name
			case *ast.SelectorExpr:
				if id, ok := fun.X.(*ast.Ident); ok {
					_ = id
				}
				name = fun.Sel.Name
			default:
				return true
			}
			keys, ok := nameToKeys[name]
			if !ok {
				return true
			}
			for _, key := range keys {
				if _, isDecl := decls[key]; !isDecl {
					continue
				}
				if fanIn[key] == nil {
					fanIn[key] = map[string]int{}
				}
				fanIn[key][callerRel]++
			}
			return true
		})
		return nil
	})

	type row struct {
		key     declKey
		sites   int
		files   int
		callers []string
	}
	var rows []row
	for key, callers := range fanIn {
		sites := 0
		for _, c := range callers {
			sites += c
		}
		callerList := make([]string, 0, len(callers))
		for c := range callers {
			callerList = append(callerList, c)
		}
		sort.Strings(callerList)
		rows = append(rows, row{key: key, sites: sites, files: len(callers), callers: callerList})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].sites != rows[j].sites {
			return rows[i].sites > rows[j].sites
		}
		return rows[i].files > rows[j].files
	})

	fmt.Println("TOP 20 (by call sites, name-collisions may inflate):")
	for i, r := range rows {
		if i >= 20 {
			break
		}
		fmt.Printf("%4d sites / %3d files  %s  —  %s\n", r.sites, r.files, r.key.symbol, r.key.path)
	}
}
GOEOF

