perl << 'PERL'
use strict;
use warnings;

my $root = "/bench/repo";

sub read_file {
    my ($p) = @_;
    open my $fh, '<', $p or return '';
    local $/; my $c = <$fh>; close $fh; return $c;
}

sub pkg_name {
    my ($path) = @_;
    my $c = read_file($path);
    return $1 if $c =~ /^package\s+(\w+)/m;
    return '';
}

# decls: key = path\x00symbol, value = {name, recv, pkg, symbol}
my %decls;
open my $if, '<', '/tmp/internal_files.txt' or die $!;
while (<$if>) {
    chomp; my $full = $_;
    my $rel = substr($full, length($root)+1);
    my $pkg = pkg_name($full);
    my $content = read_file($full);
    while ($content =~ /^func (?:\([^)]+\)\s+)?(?:\*?(\w+)\s+)?(\w+)\(/mg) {
        my ($recv, $name) = ($1, $2);
        next if $name eq 'init';
        my $symbol = $recv ? "($recv).$name" : $name;
        my $key = "$rel\x00$symbol";
        $decls{$key} = {name=>$name, recv=>$recv, pkg=>$pkg, symbol=>$symbol, path=>$rel};
    }
}
close $if;

# Build import map per caller file: alias -> import path
my %imports; # caller_rel -> {alias => import_path}
open my $af, '<', '/tmp/all_go_files.txt' or die $!;
while (<$af>) {
    chomp; my $full = $_;
    my $rel = substr($full, length($root)+1);
    my $content = read_file($full);
    while ($content =~ /^import\s+(?:\(\s*)?((?:[^\n;]+(?:\n|$))+?)(?:\s*\)|\s*$)/mg) {
        my $block = $1;
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias = (split '/', $path)[-1] unless defined $alias && $alias ne '';
            $imports{$rel}{$alias} = $path;
        }
    }
    # single-line import
    while ($content =~ /^import\s+(?:(\w+)\s+)?"(github.com\/usememos\/memos\/internal\/[^"]+)"/mg) {
        my ($alias, $path) = ($1, $2);
        $alias = (split '/', $path)[-1] unless defined $alias && $alias ne '';
        $imports{$rel}{$alias} = $path;
    }
}
close $af;

# Map internal import path prefix to decl keys in that package dir
my %path_prefix_to_keys;
for my $key (keys %decls) {
    my ($path, $symbol) = split /\x00/, $key, 2;
    my $dir = $path; $dir =~ s/\/[^\/]+$//;
    push @{$path_prefix_to_keys{"internal/$dir"}}, $key;
    # also exact package path without subdirs - map by import path ending
    my $import_path = "github.com/usememos/memos/" . ($path =~ s/\.go$//r);
    $import_path =~ s/\/[^\/]+$//;
    push @{$path_prefix_to_keys{$import_path}}, $key;
}

my %fan_sites;
my %fan_files;

for my $caller (keys %imports) {
    my $content = read_file("$root/$caller");
    my @lines = split /\n/, $content;

    # same-package unqualified calls if caller is internal
    my $caller_pkg = '';
    $caller_pkg = pkg_name("$root/$caller") if index($caller, 'internal/') == 0;

    for my $key (keys %decls) {
        my $d = $decls{$key};
        my ($decl_path, $symbol) = split /\x00/, $key, 2;
        my $name = $d->{name};
        my $decl_pkg = $d->{pkg};
        my $import_path = "github.com/usememos/memos/" . ($decl_path =~ s/\.go$//r);
        $import_path =~ s/\/[^\/]+$//;

        my @aliases;
        for my $alias (keys %{$imports{$caller}}) {
            push @aliases, $alias if $imports{$caller}{$alias} eq $import_path;
        }

        for my $line (@lines) {
            next if $line =~ /\bfunc\b/;

            # qualified calls alias.Name(
            for my $alias (@aliases) {
                my $pat = qr/\b\Q$alias\E\.\Q$name\E\s*\(/;
                if ($line =~ /$pat/g) {
                    $fan_sites{$key}++ while $line =~ /$pat/g;
                    $fan_files{$key}{$caller} = 1;
                }
            }

            # same package unqualified
            if ($caller_pkg && $caller_pkg eq $decl_pkg && index($caller, 'internal/') == 0) {
                # avoid recv.method false positives handled separately
                if (!$d->{recv}) {
                    my $pat = qr/(?<![.\w])\Q$name\E\s*\(/;
                    if ($line =~ /$pat/) {
                        $fan_sites{$key}++;
                        $fan_files{$key}{$caller} = 1;
                    }
                } else {
                    my $recv = $d->{recv};
                    my $pat = qr/(?<![.\w])\Q$recv\E\.\Q$name\E\s*\(/;
                    if ($line =~ /$pat/) {
                        $fan_sites{$key}++;
                        $fan_files{$key}{$caller} = 1;
                    }
                }
            }
        }
    }
}

my @ranked = sort {
    ($fan_sites{$b}//0) <=> ($fan_sites{$a}//0)
    || (scalar(keys %{$fan_files{$b}//{}}) <=> scalar(keys %{$fan_files{$a}//{}}))
} keys %decls;

print "TOP 25 (import-aware):\n";
for my $i (0..24) {
    last unless $ranked[$i];
    my $key = $ranked[$i];
    my $d = $decls{$key};
    my $sites = $fan_sites{$key} // 0;
    my $files = scalar keys %{$fan_files{$key}//{}};
    print sprintf("%4d sites / %3d files  %s  —  %s\n", $sites, $files, $d->{symbol}, $d->{path});
}
